    (composer_id, title, title_en, type, opus_number, catalogue_system, catalogue_number, composition_year, origin, editor_locked)
SELECT c.id, '칸타타 <Berenice, che fai?>', 'Scena di Berenice "Berenice, che fai?"', 'song', 'Hob. XXIVa:10', NULL, NULL, 1795, 'manual', 1
FROM composers c
WHERE c.id = 16
AND NOT EXISTS (
    SELECT 1 FROM pieces existing
    WHERE existing.composer_id = c.id AND existing.title = '칸타타 <Berenice, che fai?>'
)
AND NOT EXISTS (
    SELECT 1 FROM piece_identifiers taken
    WHERE taken.namespace = 'musicbrainz_work' AND taken.external_id = 'aaa623ef-623e-4e9f-8dd5-5722f5839c5a'
);

